/**
 * The results when searching for packages.
 * @class SearchResults
 * @private
 */
export default class SearchResults {
    /**
     * The raw list of dev packages to ignore
     * @name SearchResult#dev
     * @type {string[]}
     * @private
     */
    private _dev;
    /**
     * The raw list of dev packages to include
     * @name SearchResult#prod
     * @type {string[]}
     * @private
     */
    private _prod;
    /**
     * The collection of all node_modules
     * by walking through the tree.
     * @name SearchResult#_all
     * @type {string[]}
     * @private
     */
    private _all;
    /**
     * The current working directory
     * @name SearchResult#cwd
     * @type {string}
     * @private
     */
    private _cwd;
    /**
     * @constructor
     */
    constructor(cwd: string);
    /**
     * Remove the redundant options and excludes
     * any production modules.
     * @method SearchResult#process
     * @return {string[]} List of packages ignore list
     */
    process(): string[];
    /**
     * For sub modules, we'll add the .syncignore file to ignore
     * any local files that shouldn't be synced.
     * @method SearchResult#appendFile
     * @param {string} dir Root directory of module
     */
    appendFile(dir: string): void;
    /**
     * Add a list of item to append to dev
     * @method SearchResult#appendDevList
     * @param {string[]} list The list of entries from .syncignore
     * @param {string} [dir] Root directory of module if list are relative
     */
    appendDevList(list: string[], dir?: string): void;
    /**
     * Add the list of remaining files.
     * @method SearchResult#appendAll
     * @param {string[]} list The list of relative entries from .syncignore
     */
    appendAll(list: string[], dir: string): void;
    /**
     * Add to the list of dev dependencies we should ignore
     * @method SearchResult#appendDev
     * @param {string} modulePath The root directory
     */
    appendDev(modulePath: string): void;
    /**
     * Add to the list of production dependencies we should not ignore
     * @method SearchResult#appendProd
     * @param {string} modulePath The root directory
     */
    appendProd(modulePath: string): void;
    /**
     * Destroy and don't use after this
     * @method SearchResult#destroy
     */
    destroy(): void;
}
